const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[k]||paths.box}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:2}).format(Number(n)||0);
const num=n=>new Intl.NumberFormat('es-PE',{maximumFractionDigits:2}).format(n);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const uid=p=>`${p}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,6)}`;
const datefmt=d=>new Date(d+'T12:00:00').toLocaleDateString('es-PE',{day:'2-digit',month:'short'});
const seed=()=>{
 const customers=[['CLI-001','Innovatech Perú','ventas@innovatech.example','Corporativo'],['CLI-002','Grupo Horizonte','compras@horizonte.example','Corporativo'],['CLI-003','Valeria Mendoza','valeria@example.com','Minorista'],['CLI-004','Estudio Norte','hola@norte.example','Pyme'],['CLI-005','Diego Ramírez','diego@example.com','Minorista'],['CLI-006','Andes Digital','equipo@andes.example','Pyme']].map(([id,name,email,segment])=>({id,name,email,segment,status:'Activo'}));
 const products=[['PRD-001','Laptop Pro 14','Tecnología',3290,24,5],['PRD-002','Monitor 27 pulgadas','Tecnología',890,18,5],['PRD-003','Teclado inalámbrico','Accesorios',159,7,10],['PRD-004','Mouse ergonómico','Accesorios',89,36,12],['PRD-005','Silla ejecutiva','Oficina',690,4,6],['PRD-006','Escritorio minimal','Oficina',950,12,4],['PRD-007','Hub USB-C','Accesorios',129,8,10],['PRD-008','Auriculares Studio','Audio',249,21,5]].map(([id,name,category,price,stock,min])=>({id,name,category,price,stock,min,status:'Activo'}));
 const sellers=['Sandro','Jordy','Josue','Marco','Victor'].map((name,i)=>({id:`EMP-00${i+1}`,name,email:`${name.toLowerCase()}@salesia.example`,status:'Activo',goal:35000}));
 const sales=Array.from({length:48},(_,i)=>{const p=products[i%products.length],qty=i%4+1,d=new Date();d.setDate(d.getDate()-(47-i)%30);return {id:`VTA-${String(1001+i)}`,date:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,customer:customers[i%6].id,seller:sellers[i%5].id,items:[{product:p.id,qty,price:p.price}],total:p.price*qty,status:i%7===0?'Pendiente':'Pagada',method:['Transferencia','Tarjeta','Efectivo'][i%3]};});
 return {version:1,company:{name:'Comercial Enterprise',ruc:'',email:'',address:''},categories:['Tecnología','Accesorios','Oficina','Audio'],customers,products,sellers,sales,orders:[{id:'PED-001',date:today(),customer:'CLI-002',product:'PRD-001',qty:2,status:'Pendiente'},{id:'PED-002',date:today(),customer:'CLI-004',product:'PRD-005',qty:1,status:'Preparando'}],movements:[],analyses:[],findings:[],exports:[],audit:[],users:[{id:'USR-001',name:'Sandro',email:'sandro@salesia.example',role:'Administrador',status:'Activo'},{id:'USR-002',name:'Jordy',email:'jordy@salesia.example',role:'Vendedor',status:'Activo'}]};
};
const KEY='salesia.enterprise.ui.v1';let storageOK=true,state;
try{const saved=localStorage.getItem(KEY);state=saved?JSON.parse(saved):seed();if(!state||state.version!==1||!Array.isArray(state.sales))throw Error('Datos incompatibles');}catch(e){state=seed();storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;return true;}catch(e){storageOK=false;toast('No se pudo guardar en el navegador. Exporta un respaldo.');return false;}}
function log(action){state.audit.unshift({id:uid('AUD'),date:new Date().toLocaleString('es-PE'),user:'Sandro (demo)',action});save();}
let current='inicio',sub='resumen',query='',filter='',period='30',lastBayes=null,toastTimer;
const customer=id=>state.customers.find(c=>c.id===id)?.name||'Cliente eliminado';
const product=id=>state.products.find(c=>c.id===id)?.name||'Producto eliminado';
const seller=id=>state.sellers.find(c=>c.id===id)?.name||'Vendedor';
const sum=a=>a.reduce((x,y)=>x+y,0);
function stats(values){if(!values.length)return {n:0,total:0,mean:0,median:0,min:0,max:0};const a=[...values].sort((x,y)=>x-y),m=Math.floor(a.length/2);return {n:a.length,total:sum(a),mean:sum(a)/a.length,median:a.length%2?a[m]:(a[m-1]+a[m])/2,min:a[0],max:a[a.length-1]};}
function bayes(prior,likelihood,falsePositive){const evidence=prior*likelihood+(1-prior)*falsePositive;if(![prior,likelihood,falsePositive].every(n=>Number.isFinite(n)&&n>=0&&n<=1)||evidence===0)throw Error('Usa probabilidades entre 0 y 100. La evidencia debe ser mayor que cero.');return {posterior:prior*likelihood/evidence,evidence};}
function salesInPeriod(){if(period==='all')return state.sales;const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-Number(period)+1);return state.sales.filter(s=>new Date(s.date+'T12:00:00')>=cutoff);}
function pill(s){return `<span class="pill ${['Pagada','Activo','Completado','Confirmado','Normal'].includes(s)?'green':['Pendiente','Preparando','Stock bajo'].includes(s)?'amber':['Inactivo','Anulada','Cancelado','Agotado'].includes(s)?'red':''}">${esc(s)}</span>`;}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4200);}
function modal(title,html){document.querySelector('#dialog-title').textContent=title;document.querySelector('#dialog-body').innerHTML=html;document.querySelector('#dialog').showModal();}
function closeModal(){document.querySelector('#dialog').close();}
const button=(label,action,primary=false,extra='')=>`<button class="btn ${primary?'primary':''}" data-action="${action}" ${extra}>${esc(label)}</button>`;
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>${body}</section>`;}
function card(label,value,note,k='chart'){return `<article class="stat"><div class="stat-label">${label}<span class="stat-icon">${icon(k)}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></article>`;}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty" colspan="${headers.length}"><strong>No hay resultados</strong>Prueba otra búsqueda o crea el primer registro.</td></tr>`}</tbody></table></div>`;}
function toolbar(placeholder='Buscar por nombre o código…',options=[]){return `<div class="toolbar"><input class="filter-input" id="table-search" type="search" aria-label="Buscar registros" placeholder="${placeholder}" value="${esc(query)}">${options.length?`<select id="table-filter" aria-label="Filtrar registros"><option value="">Todos los estados</option>${options.map(o=>`<option ${filter===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`:''}</div>`;}
function matches(v,status){return (!query||String(v).toLowerCase().includes(query.toLowerCase()))&&(!filter||status===filter);}
function tablePanel(title,subtitle,headers,rows,opts=[]){return panel(title,subtitle,toolbar(undefined,opts)+table(headers,rows)+`<div class="table-foot"><span>${rows.length} registro${rows.length===1?'':'s'} visibles</span><span>Datos de demostración</span></div>`);}
function opts(arr,selected,key='id',label='name'){return arr.map(x=>`<option value="${esc(x[key])}" ${x[key]===selected?'selected':''}>${esc(x[label])}</option>`).join('');}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function selectField(label,name,values,selected){return `<label class="field">${label}<select name="${name}">${values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
const formEnd=label=>`<div class="form-actions">${button('Cancelar','close')}<button class="btn primary" type="submit">${label||'Guardar cambios'}</button></div>`;
function periodSelect(){return `<select class="period" id="period" aria-label="Periodo de análisis"><option value="7" ${period==='7'?'selected':''}>Últimos 7 días</option><option value="30" ${period==='30'?'selected':''}>Últimos 30 días</option><option value="all" ${period==='all'?'selected':''}>Todo el historial</option></select>`;}
function navigate(){const parts=location.hash.slice(1).split('/');current=MODULES.some(m=>m[0]===parts[0])?parts[0]:'inicio';const m=MODULES.find(m=>m[0]===current);sub=m[4].some(s=>s[0]===parts[1])?parts[1]:m[4][0][0];query='';filter='';document.body.classList.remove('menu-open');render();}
function render(){const m=MODULES.find(m=>m[0]===current);document.title=`${m[1]} | SalesIA Enterprise`;document.querySelector('#breadcrumb').textContent=m[1];document.querySelector('#nav').innerHTML=MODULES.map(x=>`${x[3]?`<div class="nav-label">${x[3]}</div>`:''}<a class="nav-item ${current===x[0]?'active':''}" href="#${x[0]}/${x[4][0][0]}" ${current===x[0]?'aria-current="page"':''}>${icon(x[2])}<span>${x[1]}</span>${x[0]==='insights'?`<span class="nav-count">${findings().length}</span>`:''}</a>${current===x[0]&&x[4].length>1?`<div class="subnav">${x[4].map(s=>`<a class="${sub===s[0]?'active':''}" href="#${x[0]}/${s[0]}">${s[1]}</a>`).join('')}</div>`:''}`).join('');
 document.querySelector('.workspace>div').innerHTML=`${esc(state.company.name)}<small>Espacio de demostración</small>`;
 const desc={inicio:'Una visión clara de tu operación, tus resultados y tus próximas decisiones.',ventas:'Gestiona el ciclo comercial, desde el pedido hasta el pago.',clientes:'Conoce a tus clientes y construye relaciones comerciales duraderas.',productos:'Un catálogo organizado para una operación más eficiente.',inventario:'Controla las existencias y anticipa tus necesidades de reposición.',equipo:'Tu equipo comercial, sus objetivos y sus resultados.',analytics:'Convierte las operaciones comerciales en evidencia estadística.',probabilidad:'Explora eventos, distribuciones y probabilidades comerciales.',insights:'Hallazgos explicables, calculados a partir de tus ventas.',reportes:'Información comercial y estadística, lista para compartir.',administracion:'Gestiona la empresa, el equipo y la trazabilidad del espacio de trabajo.'};
 const adds={ventas:['Nueva venta','new-sale'],clientes:['Nuevo cliente','new-customer'],productos:['Nuevo producto','new-product'],inventario:['Registrar movimiento','movement'],equipo:['Nuevo vendedor','new-seller'],administracion:sub==='usuarios'?['Nuevo usuario','new-user']:null};
 const headingAction=current==='inicio'?`<div class="actions">${periodSelect()}${button('+ Nueva venta','new-sale',true)}</div>`:adds[current]?button('+ '+adds[current][0],adds[current][1],true):['analytics','probabilidad'].includes(current)?periodSelect():button('Exportar datos','export');
 document.querySelector('#content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">${current==='inicio'?'TU CENTRO DE CONTROL':'WORKSPACE / '+m[1].toUpperCase()}</div><h1>${current==='inicio'?'Resumen ejecutivo':m[1]}</h1><p class="description">${desc[current]}</p></div>${headingAction}</div>${m[4].length>1?`<div class="tabs" aria-label="Secciones de ${m[1]}">${m[4].map(s=>`<a class="tab ${s[0]===sub?'active':''}" ${s[0]===sub?'aria-current="page"':''} href="#${current}/${s[0]}">${s[1]}</a>`).join('')}</div>`:''}${!storageOK?'<div class="callout">El almacenamiento local no está disponible. Exporta un respaldo antes de cerrar.</div>':''}${content()}`;
}
function content(){switch(current){case'inicio':return dashboard();case'ventas':return salesView();case'clientes':return customersView();case'productos':return productsView();case'inventario':return inventoryView();case'equipo':return teamView();case'analytics':return analyticsView();case'probabilidad':return probabilityView();case'insights':return insightsView();case'reportes':return reportsView();case'administracion':return adminView();}}
function revenueChart(sales){const grouped=Object.create(null);sales.forEach(s=>grouped[s.date]=(grouped[s.date]||0)+s.total);const entries=Object.entries(grouped).sort((a,b)=>a[0].localeCompare(b[0]));if(!entries.length)return '<div class="empty">Registra ventas para visualizar su evolución.</div>';const max=Math.max(...entries.map(e=>e[1]),1),w=560,h=145;const pts=entries.map((e,i)=>[48+(entries.length===1?.5:i/(entries.length-1))*w,175-e[1]/max*h]);return `<svg class="chart" viewBox="0 0 640 220" role="img" aria-label="Ventas diarias en soles del periodo seleccionado"><defs><linearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#328d83" stop-opacity=".19"/><stop offset="100%" stop-color="#328d83" stop-opacity="0"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="48" x2="610" y1="${175-v*h}" y2="${175-v*h}" stroke="#edf1f4" stroke-dasharray="3 4"/><text x="0" y="${179-v*h}">${num(max*v/1000)}k</text>`).join('')}<path d="M${pts[0][0]},175 L${pts.map(p=>p.join(',')).join(' L')} L${pts.at(-1)[0]},175 Z" fill="url(#chartFill)"/><path d="M${pts.map(p=>p.join(',')).join(' L')}" fill="none" stroke="#328d83" stroke-width="2.3"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.5" fill="#328d83"><title>${datefmt(entries[i][0])}: ${money(entries[i][1])}</title></circle>`).join('')}${entries.filter((_,i)=>i%Math.max(1,Math.ceil(entries.length/6))===0).map(e=>{const i=entries.indexOf(e);return `<text x="${pts[i][0]}" y="208" text-anchor="middle">${datefmt(e[0])}</text>`;}).join('')}</svg>`;}
function categoryData(){const grouped=Object.create(null);salesInPeriod().forEach(s=>s.items.forEach(i=>{const c=state.products.find(p=>p.id===i.product)?.category||'Otros';grouped[c]=(grouped[c]||0)+i.qty*i.price;}));return Object.entries(grouped).sort((a,b)=>b[1]-a[1]);}
function categoryChart(){const data=categoryData(),total=sum(data.map(d=>d[1])),colors=['#247e76','#548aaf','#a6c5cd','#dbdfd3'];let a=0;const stops=data.map((d,i)=>{const b=a+d[1]/(total||1)*100,s=`${colors[i%colors.length]} ${a}% ${b}%`;a=b;return s;});return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(${stops.join(',')||'#eef2f4 0% 100%'})"><div><strong>${state.products.length}</strong>productos</div></div><div class="legend-list">${data.map((d,i)=>`<div class="legend-row"><i style="background:${colors[i%colors.length]}"></i>${esc(d[0])}<strong>${(d[1]/(total||1)*100).toFixed(1)}%</strong></div>`).join('')||'<span class="tiny muted">Sin ventas</span>'}</div></div>`;}
function findings(){const a=stats(salesInPeriod().map(s=>s.total)),low=state.products.filter(p=>p.stock<=p.min),pending=state.sales.filter(s=>s.status==='Pendiente');const out=[];if(low.length)out.push({title:`${low.length} productos requieren reposición`,text:`${low.map(p=>p.name).join(', ')} se encuentran en el mínimo definido o por debajo.`,link:'#inventario/alertas',tag:'Inventario'});if(a.n)out.push({title:'Comprende el valor de tus ventas',text:`El ticket promedio es ${money(a.mean)} y la mediana ${money(a.median)}, sobre ${a.n} ventas del periodo.`,link:'#analytics/estadistica',tag:'Estadística'});if(pending.length)out.push({title:`${pending.length} ventas pendientes de pago`,text:`Un total de ${money(sum(pending.map(s=>s.total)))} está pendiente de cobro. Prioriza su seguimiento.`,link:'#ventas/pagos',tag:'Cobranza'});return out;}
function insightList(){return findings().map(f=>`<a class="insight" href="${f.link}"><span class="insight-icon">↗</span><div><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p></div></a>`).join('')||'<p class="muted">Sin hallazgos para este periodo.</p>';}
function saleRows(sales,actions=true){return [...sales].sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id)).map(s=>[`<strong>${esc(s.id)}</strong><small>${datefmt(s.date)}</small>`,esc(customer(s.customer)),esc(seller(s.seller)),`<strong>${money(s.total)}</strong>`,pill(s.status),...(actions?[button('Ver detalle','sale-detail',false,`data-id="${esc(s.id)}"`)]:[])]);}
function dashboard(){const sales=salesInPeriod(),s=stats(sales.map(s=>s.total)),low=state.products.filter(p=>p.stock<=p.min).length;return `<div class="welcome"><span class="welcome-icon">${icon('spark')}</span><div><h3>Buenas decisiones comienzan con buenos datos.</h3><p>Revisa tu operación y descubre oportunidades en un solo lugar.</p></div><a href="#analytics/resumen">Explorar Analytics ↗</a></div><div class="stats">${card('Ventas registradas',money(s.total),`${s.n} operaciones en el periodo`,'money')}${card('Ticket promedio',money(s.mean),'Media aritmética por transacción','chart')}${card('Clientes activos',state.customers.filter(c=>c.status==='Activo').length,`${new Set(sales.map(s=>s.customer)).size} con compras en el periodo`,'users')}${card('Alertas de inventario',String(low).padStart(2,'0'),'<strong>Requieren atención</strong> Stock mínimo','box')}</div><div class="grid-main">${panel('Evolución de ventas','Ingresos comerciales registrados · PEN',`<div class="panel-body"><div class="chart-summary"><div>Total del periodo<strong>${money(s.total)}</strong></div><span class="pill green">${s.n} transacciones</span></div>${revenueChart(sales)}</div>`,`<span class="legend"><span><b></b>Ventas</span></span>`)}${panel('Ventas por categoría','Participación sobre el importe vendido',`<div class="panel-body">${categoryChart()}</div><div class="panel-foot"><span>${categoryData().length} categorías con ventas</span><a class="link" href="#productos/catalogo">Ver catálogo →</a></div>`)}</div><div class="grid-main">${panel('Últimas ventas','Actividad reciente de tu negocio',table(['Operación','Cliente','Vendedor','Total','Estado'],saleRows(sales.slice(-5),false)),`<a href="#ventas/historial" class="link">Ver todas →</a>`)}${panel('Insights comerciales','Reglas estadísticas · Evidencia de tus datos',`<div class="panel-body">${insightList()}</div>`,`<span class="pill green">${findings().length} hallazgos</span>`)}</div><div class="quick-links">${[['cart','Registrar venta','ventas/nueva'],['users','Gestionar clientes','clientes/directorio'],['chart','Analizar resultados','analytics/estadistica'],['file','Generar reporte','reportes/comerciales']].map(([i,l,h])=>`<a class="quick-link" href="#${h}"><span>${icon(i)}</span>${l}<b>↗</b></a>`).join('')}</div>`;}
function salesView(){if(sub==='nueva')return panel('Registrar una venta','Los precios incluyen impuestos. El registro actualiza el stock de la demo.',`<div class="panel-body">${saleForm()}</div>`);if(sub==='pedidos')return panel('Seguimiento de pedidos','Confirma un pedido para convertirlo en venta y descontar el stock.',`<div class="toolbar">${button('+ Nuevo pedido','new-order',true)}</div>`+table(['Pedido','Cliente','Producto','Cantidad','Estado','Acciones'],state.orders.filter(o=>matches(o.id+customer(o.customer),o.status)).map(o=>[esc(o.id),esc(customer(o.customer)),esc(product(o.product)),o.qty,pill(o.status),o.status==='Completado'?'<span class="tiny muted">Venta registrada</span>':`<div class="row-actions">${button('Preparar','order-prepare',false,`data-id="${o.id}"`)}${button('Convertir en venta','order-sell',false,`data-id="${o.id}"`)}</div>`])));if(sub==='pagos'){const pending=state.sales.filter(s=>s.status==='Pendiente'),paid=state.sales.filter(s=>s.status==='Pagada');return `<div class="stats">${card('Cobrado',money(sum(paid.map(s=>s.total))),`${paid.length} ventas pagadas`,'money')}${card('Por cobrar',money(sum(pending.map(s=>s.total))),`${pending.length} ventas pendientes`,'money')}${card('Métodos disponibles','3','Efectivo, tarjeta y transferencia','cart')}${card('Operaciones',state.sales.length,'Historial completo','file')}</div>`+tablePanel('Control de pagos','Cobros completos por venta. Sin pagos parciales en esta interfaz.', ['Venta','Cliente','Importe','Método','Estado','Acción'],state.sales.filter(s=>matches(s.id+customer(s.customer),s.status)).map(s=>[esc(s.id),esc(customer(s.customer)),money(s.total),esc(s.method),pill(s.status),s.status==='Pendiente'?button('Registrar cobro','collect',false,`data-id="${s.id}"`):'<span class="tiny muted">Pago registrado</span>']),['Pagada','Pendiente']);}return tablePanel('Historial de ventas','Consulta operaciones, importes y estados del ciclo comercial.',['Operación','Cliente','Vendedor','Total','Estado','Detalle'],saleRows(state.sales.filter(s=>matches(s.id+customer(s.customer)+seller(s.seller),s.status))),['Pagada','Pendiente']);}
function customersView(){if(sub==='segmentos'){return `<div class="report-grid">${['Corporativo','Pyme','Minorista'].map(seg=>{const clients=state.customers.filter(c=>c.segment===seg),sales=state.sales.filter(s=>clients.some(c=>c.id===s.customer));return `<article class="report-card"><span class="report-icon">${icon('users')}</span><h3>${seg}</h3><div class="stat-value">${clients.length}</div><p>${sales.length} compras registradas<br>${money(sum(sales.map(s=>s.total)))} en ventas</p><a class="btn" href="#clientes/directorio">Ver directorio</a></article>`;}).join('')}</div>`;}if(sub==='historial')return tablePanel('Historial por cliente','Ventas acumuladas y frecuencia de compra.',['Cliente','Segmento','Compras','Total comprado','Ticket promedio','Última compra'],state.customers.filter(c=>matches(c.name+c.id,c.segment)).map(c=>{const sales=state.sales.filter(s=>s.customer===c.id),s=stats(sales.map(s=>s.total));return [esc(c.name),pill(c.segment),s.n,money(s.total),money(s.mean),sales.length?datefmt(sales.map(s=>s.date).sort().at(-1)):'Sin compras'];}),['Corporativo','Pyme','Minorista']);return tablePanel('Directorio de clientes','Información comercial centralizada y lista para consultar.',['Cliente','Correo','Segmento','Estado','Acciones'],state.customers.filter(c=>matches(c.name+c.id+c.email,c.status)).map(c=>[`<strong>${esc(c.name)}</strong><small>${esc(c.id)}</small>`,esc(c.email),pill(c.segment),pill(c.status),button('Editar ficha','edit-customer',false,`data-id="${c.id}"`)]),['Activo','Inactivo']);}
function productsView(){if(sub==='categorias')return panel('Categorías de productos','Organiza el catálogo comercial.',`<div class="toolbar">${button('+ Nueva categoría','new-category',true)}</div>`+table(['Categoría','Productos','Unidades en stock'],state.categories.map(c=>[esc(c),state.products.filter(p=>p.category===c).length,sum(state.products.filter(p=>p.category===c).map(p=>p.stock))])));return tablePanel(sub==='precios'?'Precios y disponibilidad':'Catálogo de productos','Precios finales en soles. Utiliza movimientos para modificar existencias.',['Producto','Categoría','Precio final','Stock','Estado','Acciones'],state.products.filter(p=>matches(p.name+p.id+p.category,p.status)).map(p=>[`<strong>${esc(p.name)}</strong><small>${p.id}</small>`,esc(p.category),`<strong>${money(p.price)}</strong>`,`${p.stock} unidades`,pill(p.status),button('Editar','edit-product',false,`data-id="${p.id}"`)]),['Activo','Inactivo']);}
function inventoryView(){if(sub==='movimientos')return tablePanel('Historial de movimientos','Trazabilidad desde que empezaste a utilizar la demo. El stock semilla es un saldo inicial.',['Fecha','Producto','Tipo','Cantidad','Motivo'],state.movements.filter(m=>matches(product(m.product)+m.reason,m.type)).map(m=>[esc(m.date),esc(product(m.product)),pill(m.type),`${m.type==='Entrada'?'+':'−'}${m.qty}`,esc(m.reason)]),['Entrada','Salida']);const products=state.products.filter(p=>(sub!=='alertas'||p.stock<=p.min)&&matches(p.name+p.id));return `<div class="stats">${card('Unidades disponibles',sum(state.products.map(p=>p.stock)),'Existencias actuales','layers')}${card('Productos en catálogo',state.products.length,'Referencias registradas','box')}${card('Bajo el mínimo',state.products.filter(p=>p.stock<=p.min).length,'Incluye productos agotados','target')}${card('Valor a precio de venta',money(sum(state.products.map(p=>p.stock*p.price))),'No equivale al costo de inventario','money')}</div>`+tablePanel(sub==='alertas'?'Productos que requieren atención':'Control de existencias','El umbral de reposición se configura en la ficha de cada producto.',['Producto','Stock actual','Mínimo','Cobertura','Estado','Movimiento'],products.map(p=>[`<strong>${esc(p.name)}</strong><small>${p.id}</small>`,p.stock,p.min,`<div class="progress" style="width:95px"><span style="width:${Math.min(100,p.stock/Math.max(p.min*3,1)*100)}%"></span></div>`,pill(p.stock===0?'Agotado':p.stock<=p.min?'Stock bajo':'Normal'),button('Ajustar','movement',false,`data-id="${p.id}"`)]));}
function teamView(){if(sub==='rendimiento'){return panel('Rendimiento comercial','Resultados acumulados de demostración frente a una meta individual.',`<div class="panel-body">${state.sellers.map(s=>{const sales=state.sales.filter(v=>v.seller===s.id),total=sum(sales.map(s=>s.total));return `<div class="rank-item"><span class="avatar">${esc(s.name.slice(0,2).toUpperCase())}</span><div class="rank-name">${esc(s.name)}<small>${sales.length} ventas · Meta ${money(s.goal)}</small><div class="progress"><span style="width:${Math.min(100,total/s.goal*100)}%"></span></div></div><strong>${money(total)}<small>${(total/s.goal*100).toFixed(1)}% de la meta</small></strong></div>`;}).join('')}</div>`);}return tablePanel('Equipo comercial','Directorio de vendedores y metas de venta.',['Vendedor','Correo','Meta comercial','Estado','Acciones'],state.sellers.filter(s=>matches(s.name+s.email,s.status)).map(s=>[`<strong>${esc(s.name)}</strong><small>${s.id}</small>`,esc(s.email),money(s.goal),pill(s.status),button('Editar','edit-seller',false,`data-id="${s.id}"`)]),['Activo','Inactivo']);}
function analyticsView(){const values=salesInPeriod().map(s=>s.total),s=stats(values);if(sub==='resumen')return `<div class="stats">${card('Total vendido',money(s.total),`${s.n} observaciones`,'money')}${card('Media',money(s.mean),'Ticket promedio','chart')}${card('Mediana',money(s.median),'Valor central de las ventas','target')}${card('Venta máxima',money(s.max),'Mayor importe del periodo','cart')}</div><div class="grid-main">${panel('Distribución temporal','Ventas registradas en el periodo',`<div class="panel-body">${revenueChart(salesInPeriod())}</div>`)}${panel('Participación comercial','Por categoría de producto',`<div class="panel-body">${categoryChart()}</div>`)}</div>`+panel('Ventas por vendedor','Comparación sobre el mismo periodo.',`<div class="panel-body">${state.sellers.map(v=>{const total=sum(salesInPeriod().filter(s=>s.seller===v.id).map(s=>s.total));return `<div class="bar-row"><span>${esc(v.name)}</span><div class="progress"><span style="width:${total/Math.max(s.total,1)*100}%"></span></div><strong>${money(total)}</strong></div>`;}).join('')}</div>`);if(sub==='estadistica')return `<div class="two-col">${panel('Media y mediana','Calculadas sobre el importe final de cada venta del periodo.',`<div class="panel-body"><div class="stats" style="grid-template-columns:1fr 1fr">${card('Media',money(s.mean),`${s.n} ventas`)}${card('Mediana',money(s.median),'Valores ordenados')}</div><div class="formula">Media = suma de importes / número de ventas<br>Mediana = valor central de la serie ordenada</div><div class="callout">${s.n?`La media ${s.mean>s.median?'supera':s.mean<s.median?'está por debajo de':'coincide con'} la mediana. Una diferencia puede reflejar ventas con importes extremos; no demuestra una causa comercial.`:'No hay ventas suficientes para calcular estadísticas.'}</div>${button('Guardar este análisis','save-analysis',true)}</div>`)}${panel('Detalle de la muestra','Dataset derivado de las ventas, sin introducir datos manuales.',`<div class="panel-body">${table(['Indicador','Valor'],[['Observaciones',s.n],['Suma',money(s.total)],['Mínimo',money(s.min)],['Máximo',money(s.max)],['Diferencia media − mediana',money(s.mean-s.median)]])}<p class="tiny muted">Incluye ventas pagadas y pendientes. Los datos son de demostración.</p></div>`)}</div>`;if(sub==='variables')return panel('Diccionario de variables','Clasificación estadística aplicada a la operación comercial.',table(['Variable','Naturaleza','Tipo','Origen','Ejemplo'],[['Monto de venta','Cuantitativa','Continua (registrada a centavos)','Ventas','S/ 1,250.50'],['Unidades por venta','Cuantitativa','Discreta','Detalle de venta','3 unidades'],['Categoría de producto','Cualitativa','Nominal','Catálogo','Tecnología'],['Método de pago','Cualitativa','Nominal','Pagos','Transferencia'],['Estado de venta','Cualitativa','Nominal','Ventas','Pagada'],['Stock disponible','Cuantitativa','Discreta','Inventario','24 unidades'] ]));if(sub==='datasets')return panel('Dataset de operaciones','Vista derivada de las ventas del periodo seleccionado.',table(['Venta','Fecha','Cliente','Unidades','Importe','Estado'],salesInPeriod().map(s=>[s.id,datefmt(s.date),esc(customer(s.customer)),sum(s.items.map(i=>i.qty)),money(s.total),pill(s.status)])),button('Descargar CSV','export'));return tablePanel('Historial de análisis','Instantáneas guardadas de los cálculos estadísticos y de Bayes.',['Fecha','Tipo','Muestra / evento','Resultado'],state.analyses.filter(a=>matches(a.type+a.date)).map(a=>[esc(a.date),pill(a.type),esc(a.sample),esc(a.result)]));}
function probabilityView(){const sales=salesInPeriod();if(sub==='bayes')return `<div class="two-col">${panel('Teorema de Bayes','Escenario ilustrativo: un cliente corporativo compra tecnología.',`<div class="panel-body"><form id="bayes-form"><div class="form-grid">${field('P(A) · Cliente corporativo (%)','prior',30,'number','required min="0" max="100" step="any"')}${field('P(B|A) · Tecnología si corporativo (%)','likelihood',70,'number','required min="0" max="100" step="any"')}${field('P(B|¬A) · Tecnología si no corporativo (%)','falsePositive',20,'number','required min="0" max="100" step="any"')}</div><div class="callout">A: cliente corporativo. B: compra de tecnología. Los valores iniciales son supuestos editables, no predicciones del negocio.</div><button class="btn primary" type="submit">Calcular probabilidad posterior</button><p id="bayes-error" class="error-text" role="alert"></p></form></div>`)}${panel('Probabilidad posterior','P(A|B) · Corporativo, dado que compra tecnología.',`<div class="panel-body" id="bayes-result"><div class="result-number">${lastBayes?(lastBayes.posterior*100).toFixed(2)+'%':'—'}</div><div class="result-sub">${lastBayes?'Resultado del último cálculo':'Completa los valores y ejecuta el cálculo.'}</div><div class="formula">P(B) = P(B|A)P(A) + P(B|¬A)P(¬A)<br><br>P(A|B) = P(B|A)P(A) / P(B)</div>${lastBayes?button('Guardar análisis','save-bayes'):''}</div>`)}</div>`;if(sub==='aleatorias'){const grouped=Object.create(null);sales.forEach(s=>{const q=sum(s.items.map(i=>i.qty));grouped[q]=(grouped[q]||0)+1;});return panel('Variable aleatoria: unidades por venta','Distribución empírica discreta del periodo. No implica una distribución teórica.',table(['Valor de X','Frecuencia','P(X = x)','Porcentaje'],Object.entries(grouped).sort((a,b)=>a[0]-b[0]).map(([q,n])=>[q,n,(n/(sales.length||1)).toFixed(4),(n/(sales.length||1)*100).toFixed(2)+'%'])))+panel('Valor esperado empírico','Promedio observado de unidades por transacción.',`<div class="panel-body"><div class="result-number">${num(sales.length?sum(sales.map(s=>sum(s.items.map(i=>i.qty))))/sales.length:0)}</div><p class="result-sub">Unidades por venta · ${sales.length} observaciones</p></div>`);}const paid=sales.filter(s=>s.status==='Pagada').length;return `<div class="stats">${card('P(venta pagada)',sales.length?(paid/sales.length*100).toFixed(1)+'%':'—',`${paid} de ${sales.length} ventas`)}${card('P(venta pendiente)',sales.length?((sales.length-paid)/sales.length*100).toFixed(1)+'%':'—',`${sales.length-paid} casos observados`)}${card('Tamaño de muestra',sales.length,'Ventas del periodo','layers')}${card('Tipo de probabilidad','Empírica','Frecuencia relativa observada','target')}</div>`+panel('Probabilidad por categoría','Evento: una venta contiene al menos un producto de la categoría.',table(['Evento','Casos favorables','Total de ventas','Probabilidad'],state.categories.map(c=>{const n=sales.filter(s=>s.items.some(i=>state.products.find(p=>p.id===i.product)?.category===c)).length;return [esc(c),n,sales.length,sales.length?(n/sales.length*100).toFixed(2)+'%':'Sin datos'];})))+'<div class="callout">Una venta puede incluir varias categorías, por lo que estos eventos no son necesariamente excluyentes.</div>';}
function insightsView(){if(sub==='historial')return tablePanel('Historial de hallazgos','Observaciones conservadas en el momento de su generación.',['Fecha','Área','Hallazgo','Evidencia'],state.findings.filter(f=>matches(f.title+f.text)).map(f=>[esc(f.date),pill(f.tag),esc(f.title),esc(f.text)]));return `<div class="welcome"><span class="welcome-icon">${icon('spark')}</span><div><h3>Resultados que puedes explicar</h3><p>Reglas determinísticas sobre tus datos. Esta versión no utiliza IA generativa ni una API externa.</p></div></div><div class="report-grid">${findings().map(f=>`<article class="report-card"><span class="pill green">${esc(f.tag)}</span><h3>${esc(f.title)}</h3><p>${esc(f.text)}</p><a href="${f.link}" class="btn">Revisar evidencia ↗</a></article>`).join('')}</div><div style="margin-top:20px">${button('Guardar hallazgos actuales','save-findings',true)}</div>`;}
function reportsView(){if(sub==='historial')return tablePanel('Historial de exportaciones','Registro de archivos generados desde esta interfaz.',['Fecha','Reporte','Archivo'],state.exports.filter(r=>matches(r.name+r.file)).map(r=>[esc(r.date),esc(r.name),esc(r.file)]));const reports=sub==='estadisticos'?[['Dataset de ventas','Observaciones utilizadas para los cálculos estadísticos.','dataset'],['Resumen estadístico','Media, mediana, mínimo, máximo y tamaño de muestra.','statistics'],['Historial de análisis','Resultados guardados y cálculos de Bayes.','analyses']]:[['Ventas comerciales','Detalle de ventas, cliente, vendedor, importes y estado.','sales'],['Catálogo e inventario','Productos, precios, existencias y mínimos de stock.','products'],['Clientes y vendedores','Directorio de clientes y responsables comerciales.','customers']];return `<div class="report-grid">${reports.map(([title,description,id])=>`<article class="report-card"><span class="report-icon">${icon('file')}</span><h3>${title}</h3><p>${description}</p>${button('↓ Descargar CSV','report',false,`data-id="${id}"`)}</article>`).join('')}</div><div class="callout">Los CSV se pueden abrir en Excel. Para guardar una vista en PDF, utiliza Imprimir y selecciona «Guardar como PDF».</div>${button('Imprimir esta vista','print')}`;}
function adminView(){if(sub==='usuarios')return `<div class="callout">Perfiles de demostración. La interfaz no autentica usuarios ni aplica permisos de seguridad. El control real se implementará en el backend.</div>`+tablePanel('Usuarios del sistema','Gestiona los perfiles que se muestran en la demo.',['Usuario','Correo','Rol','Estado','Acciones'],state.users.filter(u=>matches(u.name+u.email,u.status)).map(u=>[esc(u.name),esc(u.email),pill(u.role),pill(u.status),button('Editar','edit-user',false,`data-id="${u.id}"`)]),['Activo','Inactivo']);if(sub==='roles')return panel('Matriz de permisos propuesta','Diseño de referencia para implementar autorización en FastAPI.',table(['Rol','Operación comercial','Inventario','Analítica y reportes','Administración'],[['Administrador','Completa','Completo','Completo','Completa'],['Gerente','Consulta','Consulta','Consulta y exportación','Sin acceso'],['Vendedor','Clientes, pedidos y ventas','Consulta de stock','Ventas propias','Sin acceso'],['Analista','Consulta','Consulta','Análisis y exportación','Sin acceso'],['Almacén','Consulta de productos','Movimientos y alertas','Inventario','Sin acceso']]))+'<div class="callout">Estos permisos son una propuesta visual; no son controles de acceso activos.</div>';if(sub==='auditoria')return tablePanel('Auditoría de la demo','Acciones registradas localmente. No constituye un registro de seguridad inmutable.',['Fecha y hora','Usuario','Acción'],state.audit.filter(a=>matches(a.action+a.user)).map(a=>[esc(a.date),esc(a.user),esc(a.action)]));return `<div class="two-col">${panel('Información de la empresa','Personaliza la identificación del espacio comercial.',`<div class="panel-body"><form id="company-form"><div class="form-grid">${field('Razón social','name',state.company.name,'text','required maxlength="80"')}${field('RUC (opcional)','ruc',state.company.ruc,'text','pattern="[0-9]{11}" maxlength="11"')}${field('Correo comercial','email',state.company.email,'email')}${field('Dirección','address',state.company.address,'text','maxlength="150"')}</div><div class="form-actions"><button class="btn primary" type="submit">Guardar empresa</button></div></form></div>`)}${panel('Datos y preferencias','Herramientas para conservar tu demostración.',`<div class="panel-body"><div class="setting-row"><div><h3>Respaldo de datos</h3><p>Descarga todos los registros en un archivo JSON.</p></div>${button('Exportar','backup')}</div><div class="setting-row"><div><h3>Restaurar respaldo</h3><p>Reemplaza la demo con un respaldo compatible.</p></div>${button('Importar','restore')}</div><div class="setting-row"><div><h3>Datos de ejemplo</h3><p>Vuelve al estado inicial de la interfaz.</p></div>${button('Restablecer','reset')}</div><div class="callout">Persistencia en este navegador. No existe sincronización entre equipos ni conexión a PostgreSQL en esta entrega.</div></div>`)}</div>`;}
function saleLine(productId='',qty=1){return `<div class="sale-line form-grid" style="grid-template-columns:minmax(120px,1fr) 90px 32px;margin-top:12px;align-items:end"><label class="field">Producto<select name="product" required>${opts(state.products.filter(p=>p.status==='Activo'),productId)}</select></label><label class="field">Cantidad<input name="qty" type="number" value="${qty}" min="1" max="100000" step="1" required></label><button class="icon-button" type="button" data-action="remove-line" aria-label="Quitar producto">×</button></div>`;}
function saleForm(order){return `<form id="sale-form" data-order="${order?.id||''}"><div class="form-grid"><label class="field">Cliente<select name="customer" required>${opts(state.customers.filter(c=>c.status==='Activo'),order?.customer)}</select></label><label class="field">Vendedor<select name="seller" required>${opts(state.sellers.filter(s=>s.status==='Activo'))}</select></label>${selectField('Estado de pago','status',['Pagada','Pendiente'])}${selectField('Método de pago','method',['Transferencia','Tarjeta','Efectivo'])}</div><div id="sale-lines">${saleLine(order?.product,order?.qty)}</div><div style="margin-top:12px">${button('+ Añadir producto','add-line',false,'type="button"')}</div><div class="total-box"><span>Total de la venta<small style="display:block">Precios finales · PEN</small></span><strong id="sale-total">${money((state.products.find(p=>p.id===order?.product)||state.products.find(p=>p.status==='Activo'))?.price*(order?.qty||1)||0)}</strong></div><div class="callout">La venta descuenta stock al registrarse, incluso si el pago queda pendiente. No se emiten comprobantes fiscales.</div><div id="sale-error" class="error-text" role="alert"></div><div class="form-actions"><button class="btn primary" type="submit">Confirmar y registrar venta</button></div></form>`;}
function calculateSale(form){return [...form.querySelectorAll('.sale-line')].map(line=>{const id=line.querySelector('[name="product"]').value,qty=Number(line.querySelector('[name="qty"]').value),p=state.products.find(p=>p.id===id);return {product:id,qty,price:p?.price||0};});}
function recordSale(data,items,orderId){if(!state.customers.some(c=>c.id===data.customer&&c.status==='Activo'))throw Error('Selecciona un cliente activo.');if(!state.sellers.some(s=>s.id===data.seller&&s.status==='Activo'))throw Error('Selecciona un vendedor activo.');if(!items.length)throw Error('Añade al menos un producto.');const grouped=Object.create(null);items.forEach(i=>{if(!Number.isSafeInteger(i.qty)||i.qty<=0)throw Error('La cantidad debe ser un entero positivo.');grouped[i.product]=(grouped[i.product]||0)+i.qty;});Object.entries(grouped).forEach(([id,qty])=>{const p=state.products.find(p=>p.id===id);if(!p||p.status!=='Activo')throw Error('Producto no disponible.');if(p.stock<qty)throw Error(`Stock insuficiente para ${p.name}: quedan ${p.stock} unidades.`);});if(!['Pagada','Pendiente'].includes(data.status)||!['Transferencia','Tarjeta','Efectivo'].includes(data.method))throw Error('Estado o método no válido.');const order=orderId?state.orders.find(o=>o.id===orderId):null;if(orderId&&(!order||order.status==='Completado'))throw Error('Este pedido ya fue procesado o no existe.');const normalized=Object.entries(grouped).map(([id,qty])=>({product:id,qty,price:state.products.find(p=>p.id===id).price}));const sale={id:uid('VTA').toUpperCase(),date:today(),customer:data.customer,seller:data.seller,status:data.status,method:data.method,items:normalized,total:Math.round(sum(normalized.map(i=>i.qty*i.price))*100)/100};normalized.forEach(i=>{state.products.find(p=>p.id===i.product).stock-=i.qty;state.movements.unshift({id:uid('MOV'),date:new Date().toLocaleString('es-PE'),product:i.product,qty:i.qty,type:'Salida',reason:sale.id});});state.sales.push(sale);if(order)order.status='Completado';log(`Venta registrada: ${sale.id} · ${money(sale.total)}`);return sale;}
function editEntity(type,id){const configs={customer:['customers','cliente'],product:['products','producto'],seller:['sellers','vendedor'],user:['users','usuario']},[collection,label]=configs[type],item=state[collection].find(i=>i.id===id)||{};let fields=field('Nombre','name',item.name,'text','required maxlength="80"');if(type==='product'){fields+=`<label class="field">Categoría<select name="category">${state.categories.map(c=>`<option ${item.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`+field('Precio final (S/)','price',item.price??0,'number','required min="0.01" max="100000000" step="0.01"')+field('Stock mínimo','min',item.min??5,'number','required min="0" max="100000000" step="1"');if(!id)fields+=field('Stock inicial','stock',0,'number','required min="0" max="100000000" step="1"');}else fields+=field('Correo','email',item.email,'email','required maxlength="150"');if(type==='customer')fields+=selectField('Segmento','segment',['Corporativo','Pyme','Minorista'],item.segment);if(type==='seller')fields+=field('Meta comercial (S/)','goal',item.goal??35000,'number','required min="1" max="100000000" step="0.01"');if(type==='user')fields+=selectField('Rol propuesto','role',['Administrador','Gerente','Vendedor','Analista','Almacén'],item.role);fields+=selectField('Estado','status',['Activo','Inactivo'],item.status);modal(`${id?'Editar':'Nuevo'} ${label}`,`<form id="entity-form" data-type="${type}" data-id="${id||''}"><div class="form-grid">${fields}</div><p id="entity-error" class="error-text" role="alert"></p>${formEnd()}</form>`);}
function movementForm(id){modal('Registrar movimiento',`<form id="movement-form"><div class="form-grid"><label class="field full">Producto<select name="product" required>${opts(state.products,id)}</select></label>${selectField('Tipo de movimiento','type',['Entrada','Salida'])}${field('Cantidad','qty',1,'number','required min="1" max="100000000" step="1"')}<label class="field full">Motivo<input name="reason" required maxlength="150" placeholder="Ej. Reposición del proveedor"></label></div><p id="movement-error" class="error-text" role="alert"></p>${formEnd('Registrar movimiento')}</form>`);}
function saleDetail(id){const s=state.sales.find(s=>s.id===id);if(!s)return;modal('Detalle de venta',`<div class="callout"><strong>${esc(s.id)}</strong><br>${esc(customer(s.customer))} · ${datefmt(s.date)}<br>Responsable: ${esc(seller(s.seller))} · ${esc(s.method)} · ${pill(s.status)}</div>${table(['Producto','Cantidad','Precio','Total'],s.items.map(i=>[esc(product(i.product)),i.qty,money(i.price),money(i.qty*i.price)]))}<div class="total-box"><span>Total registrado</span><strong>${money(s.total)}</strong></div><div class="form-actions">${button('Cerrar','close')}</div>`);}
function download(filename,content,mime){const blob=new Blob([content],{type:mime}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csvCell(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';}
function exportReport(type){let headers,rows,name;switch(type){case'products':headers=['Código','Producto','Categoría','Precio','Stock','Mínimo','Estado'];rows=state.products.map(p=>[p.id,p.name,p.category,p.price,p.stock,p.min,p.status]);name='Productos';break;case'customers':headers=['Código','Nombre','Correo','Tipo','Segmento o meta'];rows=[...state.customers.map(c=>[c.id,c.name,c.email,'Cliente',c.segment]),...state.sellers.map(s=>[s.id,s.name,s.email,'Vendedor',s.goal])];name='Clientes-y-vendedores';break;case'statistics':{const s=stats(salesInPeriod().map(s=>s.total));headers=['Observaciones','Suma','Media','Mediana','Mínimo','Máximo'];rows=[[s.n,s.total,s.mean,s.median,s.min,s.max]];name='Estadisticas';break;}case'analyses':headers=['Fecha','Tipo','Muestra','Resultado'];rows=state.analyses.map(a=>[a.date,a.type,a.sample,a.result]);name='Analisis';break;default:headers=['Venta','Fecha','Cliente','Vendedor','Unidades','Total','Estado','Método'];rows=(type==='dataset'?salesInPeriod():state.sales).map(s=>[s.id,s.date,customer(s.customer),seller(s.seller),sum(s.items.map(i=>i.qty)),s.total,s.status,s.method]);name=type==='dataset'?'Dataset':'Ventas';}
 const file=`SalesIA-${name}-${today()}.csv`;download(file,'\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');state.exports.unshift({date:new Date().toLocaleString('es-PE'),name,file});log('Exportación: '+file);toast('Reporte CSV descargado');if(current==='reportes'&&sub==='historial')render();}
function searchModal(){modal('Buscar en el espacio de trabajo','<input id="module-search" class="filter-input" style="width:100%" placeholder="Ventas, inventario, Bayes…" aria-label="Buscar un módulo"><div class="search-results" id="module-results"></div>');searchResults('');document.querySelector('#module-search').focus();}
function searchResults(q){document.querySelector('#module-results').innerHTML=MODULES.flatMap(m=>m[4].filter(s=>(m[1]+' '+s[1]).toLowerCase().includes(q.toLowerCase())).map(s=>`<a class="search-result" href="#${m[0]}/${s[0]}" data-action="close">${m[1]} <span class="muted">/ ${s[1]}</span></a>`)).join('')||'<p class="empty">No se encontraron módulos.</p>';}
const ACTIONS={
 'menu':()=>document.body.classList.toggle('menu-open'),'close':closeModal,'search':searchModal,'notifications':()=>modal('Alertas y seguimiento',insightList()),
 'new-sale':()=>modal('Nueva venta',saleForm()),'sale-detail':id=>saleDetail(id),
 'add-line':(_,el)=>{el.closest('form').querySelector('#sale-lines').insertAdjacentHTML('beforeend',saleLine());updateTotal(el.closest('form'));},
 'remove-line':(_,el)=>{const f=el.closest('form');if(f.querySelectorAll('.sale-line').length===1)return toast('La venta necesita al menos un producto.');el.closest('.sale-line').remove();updateTotal(f);},
 'new-customer':()=>editEntity('customer'),'edit-customer':id=>editEntity('customer',id),'new-product':()=>editEntity('product'),'edit-product':id=>editEntity('product',id),'new-seller':()=>editEntity('seller'),'edit-seller':id=>editEntity('seller',id),'new-user':()=>editEntity('user'),'edit-user':id=>editEntity('user',id),
 'new-category':()=>modal('Nueva categoría',`<form id="category-form">${field('Nombre de categoría','name','','text','required maxlength="50"')}<p class="error-text" id="category-error" role="alert"></p>${formEnd('Crear categoría')}</form>`),
 'movement':id=>movementForm(id),
 'new-order':()=>modal('Nuevo pedido',`<form id="order-form"><div class="form-grid"><label class="field">Cliente<select name="customer" required>${opts(state.customers.filter(c=>c.status==='Activo'))}</select></label><label class="field">Producto<select name="product" required>${opts(state.products.filter(p=>p.status==='Activo'))}</select></label>${field('Cantidad','qty',1,'number','required min="1" max="100000" step="1"')}</div><div class="callout">El pedido no reserva stock. La disponibilidad se valida al convertirlo en venta.</div>${formEnd('Crear pedido')}</form>`),
 'order-prepare':id=>{const o=state.orders.find(o=>o.id===id);if(o&&o.status!=='Completado'){o.status='Preparando';log('Pedido en preparación: '+id);render();toast('Pedido en preparación');}},
 'order-sell':id=>{const o=state.orders.find(o=>o.id===id);if(o&&o.status!=='Completado')modal('Confirmar pedido como venta',saleForm(o));},
 'collect':id=>{const s=state.sales.find(s=>s.id===id);if(s)modal('Registrar cobro',`<form id="collect-form" data-id="${s.id}"><div class="callout">${esc(s.id)} · ${money(s.total)} · ${esc(customer(s.customer))}</div>${selectField('Método de pago','method',['Transferencia','Tarjeta','Efectivo'],s.method)}${formEnd('Confirmar pago completo')}</form>`);},
 'save-analysis':()=>{const s=stats(salesInPeriod().map(s=>s.total));if(!s.n)return toast('Registra ventas antes de guardar un análisis.');state.analyses.unshift({date:new Date().toLocaleString('es-PE'),type:'Media y mediana',sample:`${s.n} ventas · Periodo ${period}`,result:`Media: ${money(s.mean)} · Mediana: ${money(s.median)}`});log('Análisis estadístico guardado');toast('Análisis guardado en el historial');},
 'save-bayes':()=>{if(!lastBayes)return;state.analyses.unshift({date:new Date().toLocaleString('es-PE'),type:'Bayes',sample:`P(A)=${lastBayes.prior}, P(B|A)=${lastBayes.likelihood}, P(B|¬A)=${lastBayes.falsePositive}`,result:`P(A|B)=${(lastBayes.posterior*100).toFixed(2)}%`});log('Análisis de Bayes guardado');toast('Análisis de Bayes guardado');},
 'save-findings':()=>{state.findings.unshift(...findings().map(f=>({...f,date:new Date().toLocaleString('es-PE')})));log('Hallazgos guardados');toast('Hallazgos conservados en el historial');},
 'report':id=>exportReport(id),'export':()=>exportReport(current==='productos'||current==='inventario'?'products':current==='clientes'||current==='equipo'?'customers':current==='analytics'?'dataset':'sales'),
 'print':()=>window.print(),'backup':()=>{download(`SalesIA-respaldo-${today()}.json`,JSON.stringify(state,null,2),'application/json');toast('Respaldo descargado');},
 'restore':()=>modal('Restaurar un respaldo',`<form id="restore-form"><div class="callout">Se reemplazarán todos los datos actuales de esta demo. Exporta un respaldo antes si deseas conservarlos.</div><label class="field">Archivo JSON de SalesIA<input name="file" type="file" accept=".json,application/json" required></label><p id="restore-error" class="error-text" role="alert"></p>${formEnd('Importar y reemplazar')}</form>`),
 'reset':()=>modal('Restablecer datos de ejemplo',`<p class="description">Se eliminarán los cambios locales y se restaurará la demostración inicial. Esta acción no afecta a ningún sistema externo.</p><div class="form-actions">${button('Cancelar','close')}${button('Sí, restablecer demo','confirm-reset',true)}</div>`),
 'confirm-reset':()=>{state=seed();save();lastBayes=null;closeModal();render();toast('Datos de demostración restablecidos');},
 'help':()=>modal('Bienvenido a SalesIA',`<p class="description">Una interfaz empresarial de ventas y analítica, lista para explorar sin instalar dependencias.</p><div class="flow"><span>Cliente</span><span>Pedido</span><span>Venta</span><span>Pago y stock</span><span>Analytics</span></div><ol class="description"><li>Registra clientes y productos desde el menú lateral.</li><li>Crea una venta con uno o varios productos.</li><li>Consulta los movimientos y las alertas de stock.</li><li>Explora Analytics y guarda un análisis.</li><li>Exporta reportes o un respaldo desde Administración.</li></ol><div class="callout">Demo local: sin autenticación real, base de datos remota, IA generativa ni facturación fiscal. Los datos se conservan en este navegador y ubicación de la carpeta. No ingreses información confidencial.</div><p class="tiny muted">Atajo: pulsa / para buscar un módulo. Pulsa Esc para cerrar una ventana.</p>`)
};
function updateTotal(f){const t=f.querySelector('#sale-total');if(t)t.textContent=money(sum(calculateSale(f).map(i=>i.price*i.qty)));}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){if(el.tagName==='BUTTON')e.preventDefault();const fn=ACTIONS[el.dataset.action];if(fn)fn(el.dataset.id,el);}else if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar'))document.body.classList.remove('menu-open');if(e.target.closest('#dialog a[href]'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='table-search'){query=e.target.value;const p=e.target.selectionStart;render();const n=document.querySelector('#table-search');n.focus();n.setSelectionRange(p,p);}if(e.target.id==='module-search')searchResults(e.target.value);if(e.target.closest('#sale-form'))updateTotal(e.target.closest('form'));});
document.addEventListener('change',e=>{if(e.target.id==='table-filter'){filter=e.target.value;render();}if(e.target.id==='period'){period=e.target.value;render();}if(e.target.closest('#sale-form'))updateTotal(e.target.closest('form'));});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&!document.querySelector('#dialog').open){e.preventDefault();searchModal();}if(e.key==='Escape')document.body.classList.remove('menu-open');});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));try{
 if(f.id==='sale-form'){recordSale(d,calculateSale(f),f.dataset.order);closeModal();render();toast('Venta registrada. Stock y analítica actualizados.');}
 if(f.id==='entity-form'){const type=f.dataset.type,collection={customer:'customers',product:'products',seller:'sellers',user:'users'}[type];d.name=d.name.trim();if(!d.name)throw Error('El nombre es obligatorio.');if(d.email&&state[collection].some(x=>x.email.toLowerCase()===d.email.trim().toLowerCase()&&x.id!==f.dataset.id))throw Error('Ya existe un registro con este correo.');if(type==='product'){d.price=Number(d.price);d.min=Number(d.min);if(!(d.price>0)||!Number.isInteger(d.min)||d.min<0)throw Error('Revisa el precio y stock mínimo.');if('stock'in d){d.stock=Number(d.stock);if(!Number.isInteger(d.stock)||d.stock<0)throw Error('Stock inicial no válido.');}}if(type==='seller'){d.goal=Number(d.goal);if(!(d.goal>0))throw Error('La meta debe ser positiva.');}const old=state[collection].find(x=>x.id===f.dataset.id);if(old)Object.assign(old,d);else state[collection].push({id:uid({customer:'CLI',product:'PRD',seller:'EMP',user:'USR'}[type]).toUpperCase(),...d});log(`${old?'Actualización':'Creación'}: ${d.name}`);closeModal();render();toast('Registro guardado');}
 if(f.id==='category-form'){d.name=d.name.trim();if(!d.name||state.categories.some(c=>c.toLowerCase()===d.name.toLowerCase()))throw Error('Ingresa una categoría nueva y no vacía.');state.categories.push(d.name);log('Categoría creada: '+d.name);closeModal();render();toast('Categoría creada');}
 if(f.id==='movement-form'){const p=state.products.find(p=>p.id===d.product),qty=Number(d.qty);if(!p||!Number.isSafeInteger(qty)||qty<=0)throw Error('Selecciona un producto y una cantidad válida.');if(!d.reason.trim())throw Error('Indica el motivo.');if(d.type==='Salida'&&p.stock<qty)throw Error('La salida supera el stock disponible.');p.stock+=d.type==='Entrada'?qty:-qty;state.movements.unshift({id:uid('MOV'),...d,qty,date:new Date().toLocaleString('es-PE')});log(`${d.type} de ${qty} unidades: ${p.name}`);closeModal();render();toast('Movimiento registrado');}
 if(f.id==='order-form'){const qty=Number(d.qty);if(!Number.isSafeInteger(qty)||qty<=0||!d.customer||!d.product)throw Error('Completa los datos del pedido.');state.orders.push({id:uid('PED').toUpperCase(),date:today(),...d,qty,status:'Pendiente'});log('Pedido creado');closeModal();render();toast('Pedido creado');}
 if(f.id==='collect-form'){const s=state.sales.find(s=>s.id===f.dataset.id);if(!s||s.status!=='Pendiente')throw Error('El pago ya fue registrado.');s.status='Pagada';s.method=d.method;log('Pago registrado: '+s.id);closeModal();render();toast('Cobro registrado');}
 if(f.id==='company-form'){if(!d.name.trim())throw Error('Ingresa la razón social.');state.company={...d,name:d.name.trim()};log('Información de empresa actualizada');render();toast('Empresa actualizada');}
 if(f.id==='bayes-form'){const prior=Number(d.prior)/100,likelihood=Number(d.likelihood)/100,falsePositive=Number(d.falsePositive)/100;lastBayes={...bayes(prior,likelihood,falsePositive),prior,likelihood,falsePositive};document.querySelector('#bayes-error').textContent='';document.querySelector('#bayes-result').innerHTML=`<div class="result-number">${(lastBayes.posterior*100).toFixed(2)}%</div><div class="result-sub">Probabilidad posterior de A dado B</div><div class="formula">P(B) = ${(lastBayes.evidence*100).toFixed(2)}%<br>P(A|B) = (${likelihood} × ${prior}) / ${lastBayes.evidence.toFixed(4)}</div><div class="callout">Resultado condicionado a los supuestos ingresados. No es una predicción generada por IA.</div>${button('Guardar análisis','save-bayes')}`;}
 if(f.id==='restore-form'){const file=f.querySelector('input[type="file"]').files[0];if(!file||file.size>5000000)throw Error('Selecciona un respaldo JSON de hasta 5 MB.');const data=JSON.parse(await file.text());validateBackup(data);state=data;save();closeModal();render();toast('Respaldo restaurado');}
 }catch(err){const target=f.querySelector('.error-text');if(target)target.textContent=err.message;else toast(err.message);}});
function validateBackup(d){const fail=()=>{throw Error('Respaldo no compatible o con datos inválidos. Utiliza un JSON exportado por SalesIA v1.');};const text=v=>typeof v==='string'&&v.length<=3000;const positive=n=>Number.isFinite(n)&&n>=0;const integer=n=>Number.isSafeInteger(n)&&n>=0;
 if(!d||d.version!==1||!d.company||!['name','ruc','email','address'].every(k=>text(d.company[k])))fail();
 for(const k of ['categories','customers','products','sellers','sales','orders','movements','analyses','findings','exports','audit','users'])if(!Array.isArray(d[k])||d[k].length>30000)fail();
 if(!d.categories.length||!d.categories.every(text))fail();
 for(const k of ['customers','products','sellers','users'])if(!d[k].every(x=>x&&text(x.id)&&/^[A-Za-z0-9-]+$/.test(x.id)&&text(x.name)&&['Activo','Inactivo'].includes(x.status))||new Set(d[k].map(x=>x.id)).size!==d[k].length)fail();
 if(!d.products.every(p=>d.categories.includes(p.category)&&positive(p.price)&&p.price>0&&integer(p.stock)&&integer(p.min)))fail();
 if(!d.customers.every(c=>text(c.email)&&['Corporativo','Pyme','Minorista'].includes(c.segment))||!d.sellers.every(s=>text(s.email)&&positive(s.goal)&&s.goal>0)||!d.users.every(u=>text(u.email)&&text(u.role)))fail();
 if(!d.sales.every(s=>s&&text(s.id)&&/^[A-Za-z0-9-]+$/.test(s.id)&&/^\d{4}-\d{2}-\d{2}$/.test(s.date)&&Number.isFinite(Date.parse(s.date))&&d.customers.some(c=>c.id===s.customer)&&d.sellers.some(v=>v.id===s.seller)&&['Pagada','Pendiente'].includes(s.status)&&text(s.method)&&positive(s.total)&&Array.isArray(s.items)&&s.items.length>0&&s.items.every(i=>i&&d.products.some(p=>p.id===i.product)&&integer(i.qty)&&i.qty>0&&positive(i.price))&&Math.abs(sum(s.items.map(i=>i.qty*i.price))-s.total)<.011))fail();
 if(!d.orders.every(o=>o&&/^[A-Za-z0-9-]+$/.test(o.id)&&text(o.date)&&d.customers.some(c=>c.id===o.customer)&&d.products.some(p=>p.id===o.product)&&integer(o.qty)&&o.qty>0&&['Pendiente','Preparando','Completado'].includes(o.status)))fail();
 if(!d.movements.every(m=>m&&text(m.date)&&text(m.reason)&&d.products.some(p=>p.id===m.product)&&integer(m.qty)&&m.qty>0&&['Entrada','Salida'].includes(m.type)))fail();
 for(const [k,fields] of [['analyses',['date','type','sample','result']],['findings',['date','tag','title','text']],['exports',['date','name','file']],['audit',['date','user','action']]])if(!d[k].every(x=>x&&fields.every(f=>text(x[f]))))fail();
}
window.addEventListener('hashchange',navigate);
navigate();
